def get_income_statements(ticker, period, limit=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage/audit logging store (create if absent)
    _REQ_FILE = "request_log.json"
    req_log = _load(_REQ_FILE)

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(req_log)+1}",
            "endpoint": "get_income_statements",
            "ts": now_iso,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        req_log.append(row)
        _save(_REQ_FILE, req_log)

    # Validate inputs
    if not isinstance(ticker, str) or not ticker.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string")
    if not isinstance(period, str) or period not in ("annual", "quarterly", "ttm"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "period must be one of: annual, quarterly, ttm")
    if limit is None:
        limit_val = 4
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        limit_val = limit

    instruments = _load("instruments.json")
    fin = _load("financial_statements.json")

    # Resolve active equity instrument by case-insensitive ticker
    tick_u = ticker.strip().upper()
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("asset_class") == "equity" and r.get("status") == "active":
            if isinstance(r.get("ticker"), str) and r["ticker"].upper() == tick_u:
                inst = r
                break
    if not inst:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Active equity instrument not found for ticker", ticker=tick_u)

    # Filter statements (published/restated)
    out = []
    for r in fin:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst.get("id"):
            continue
        if r.get("statement_type") != "income_statement":
            continue
        if r.get("period") != period:
            continue
        if r.get("status") not in ("published", "restated"):
            continue
        out.append(r)

    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    out.sort(key=lambda r: (_parse_dt(r.get("period_end_date")) or datetime.datetime.min), reverse=True)
    out = out[:limit_val]

    _log("ok")
    return {
        "ticker": inst.get("ticker"),
        "period": period,
        "count": len(out),
        "data": out,
    }

