def get_current_stock_price(ticker, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _REQ_FILE = "request_log.json"
    req_log = _load(_REQ_FILE)

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(req_log)+1}",
            "endpoint": "get_current_stock_price",
            "ts": now_iso,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        req_log.append(row)
        _save(_REQ_FILE, req_log)

    if not isinstance(ticker, str) or not ticker.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string")

    instruments = _load("instruments.json")
    bars = _load("price_bars.json")

    tick_u = ticker.strip().upper()
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("asset_class") == "equity" and r.get("status") == "active":
            if isinstance(r.get("ticker"), str) and r["ticker"].upper() == tick_u:
                inst = r
                break
    if not inst:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Active equity instrument not found for ticker", ticker=tick_u)

    def _parse_dt(x):
        if not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    inst_id = inst.get("id")
    candidates = []
    for r in bars:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != inst_id:
            continue
        # data_status is enum final/preliminary/corrected; "removed" not modeled; ignore anything outside enum
        if r.get("data_status") not in ("final", "preliminary", "corrected"):
            continue
        ts = _parse_dt(r.get("ts"))
        if ts is None:
            continue
        candidates.append((ts, r))

    if not candidates:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No price data available for ticker", ticker=tick_u)

    # Prefer latest 1-minute bar if exists; else most recent across any interval
    one_min = [(ts, r) for (ts, r) in candidates if r.get("interval") == "minute" and r.get("interval_multiplier") == 1]
    if one_min:
        one_min.sort(key=lambda x: x[0], reverse=True)
        latest_ts, latest = one_min[0]
    else:
        candidates.sort(key=lambda x: x[0], reverse=True)
        latest_ts, latest = candidates[0]

    price = latest.get("close")
    if not isinstance(price, (int, float)) or isinstance(price, bool):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Latest price is not available/valid for ticker", ticker=tick_u)

    _log("ok")
    return {
        "ticker": inst.get("ticker"),
        "asset_class": "equity",
        "price": float(price),
        "as_of": latest.get("ts"),
        "bar": latest,
    }

def get_historical_stock_prices(ticker, start_date, end_date, interval, interval_multiplier, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_historical_stock_prices"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts_any(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        # Accept YYYY-MM-DD, or full ISO 8601 including trailing Z
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            try:
                d = datetime.datetime.strptime(s, "%Y-%m-%d").date()
                return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            except ValueError:
                return None

    def _parse_date_param(s, field):
        # The vendor description says YYYY-MM-DD, but real calls provide full ISO timestamps.
        # Accept either, normalize to date.
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a string date", field=field)
        dt = _parse_ts_any(s)
        if not dt:
            return None, _err("VALIDATION_ERROR", f"Invalid {field} format; expected YYYY-MM-DD or ISO 8601 timestamp", field=field)
        return dt.date(), None

    def _get_requests_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _extract_ts_from_log_row(r):
        if not isinstance(r, dict):
            return None
        for k in ("ts", "timestamp", "created_at", "time"):
            if k in r:
                dt = _parse_ts_any(r.get(k))
                if dt:
                    return dt.astimezone(datetime.timezone.utc)
        return None

    def _extract_endpoint_from_log_row(r):
        if isinstance(r, dict):
            return r.get("endpoint") or r.get("path") or r.get("operation")
        return None

    def _enforce_limits():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        try:
            rate_i = int(rate) if rate is not None else None
        except Exception:
            rate_i = None
        try:
            quota_i = int(quota) if quota is not None else None
        except Exception:
            quota_i = None

        fn = _get_requests_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        if rate_i is not None and rate_i >= 0:
            window_start = now - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs[-10000:]:
                if _extract_endpoint_from_log_row(r) != endpoint:
                    continue
                ts = _extract_ts_from_log_row(r)
                if ts and ts >= window_start:
                    cnt += 1
            if cnt >= rate_i:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if quota_i is not None and quota_i >= 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs[-200000:]:
                if _extract_endpoint_from_log_row(r) != endpoint:
                    continue
                ts = _extract_ts_from_log_row(r)
                if ts and ts >= day_start:
                    cnt += 1
            if cnt >= quota_i:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _log(status, error_code=None):
        fn = _get_requests_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso()
        })
        _save(fn, logs)

    # Validate inputs first
    if not isinstance(ticker, str) or not ticker.strip():
        e = _err("VALIDATION_ERROR", "ticker must be a non-empty string", field="ticker")
        _log("error", e["error"]["code"])
        return e

    allowed_intervals = {"minute", "hour", "day", "week", "month"}
    if interval not in allowed_intervals:
        e = _err("VALIDATION_ERROR", "Invalid interval", field="interval", allowed=sorted(list(allowed_intervals)))
        _log("error", e["error"]["code"])
        return e

    if not isinstance(interval_multiplier, int):
        e = _err("VALIDATION_ERROR", "interval_multiplier must be an integer", field="interval_multiplier")
        _log("error", e["error"]["code"])
        return e
    if interval_multiplier < 1 or interval_multiplier > 1440:
        e = _err("VALIDATION_ERROR", "interval_multiplier must be between 1 and 1440", field="interval_multiplier")
        _log("error", e["error"]["code"])
        return e

    sd, err = _parse_date_param(start_date, "start_date")
    if err:
        _log("error", err["error"]["code"])
        return err
    ed, err = _parse_date_param(end_date, "end_date")
    if err:
        _log("error", err["error"]["code"])
        return err
    if sd > ed:
        e = _err("VALIDATION_ERROR", "start_date must be <= end_date", field="start_date")
        _log("error", e["error"]["code"])
        return e

    # Enforce limits (if configured)
    lim_err = _enforce_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    # Resolve active equity instrument by ticker (case-insensitive)
    inst = _load("instruments.json")
    if isinstance(inst, dict) and "rows" in inst and isinstance(inst["rows"], list):
        inst_rows = inst["rows"]
    elif isinstance(inst, list):
        inst_rows = inst
    else:
        inst_rows = []

    t_up = ticker.strip().upper()
    instrument = None
    for r in inst_rows:
        if not isinstance(r, dict):
            continue
        if (r.get("asset_class") == "equity"
                and r.get("status") == "active"
                and isinstance(r.get("ticker"), str)
                and r.get("ticker").strip().upper() == t_up):
            instrument = r
            break
    if not instrument:
        e = _err("NOT_FOUND", "No active equity instrument found for ticker", ticker=ticker)
        _log("error", e["error"]["code"])
        return e

    # Filter price bars
    pb = _load("price_bars.json")
    if isinstance(pb, dict) and "rows" in pb and isinstance(pb["rows"], list):
        bars = pb["rows"]
    elif isinstance(pb, list):
        bars = pb
    else:
        bars = []

    start_dt = datetime.datetime(sd.year, sd.month, sd.day, tzinfo=datetime.timezone.utc)
    end_dt = datetime.datetime(ed.year, ed.month, ed.day, 23, 59, 59, tzinfo=datetime.timezone.utc)

    out = []
    for b in bars:
        if not isinstance(b, dict):
            continue
        if b.get("instrument_id") != instrument.get("id"):
            continue
        if b.get("interval") != interval:
            continue
        if b.get("interval_multiplier") != interval_multiplier:
            continue
        ts = _parse_ts_any(b.get("ts"))
        if not ts:
            continue
        ts = ts.astimezone(datetime.timezone.utc)
        if ts < start_dt or ts > end_dt:
            continue
        out.append(b)

    out.sort(key=lambda x: (_parse_ts_any(x.get("ts")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)))

    resp = {
        "ticker": instrument.get("ticker"),
        "instrument_id": instrument.get("id"),
        "asset_class": instrument.get("asset_class"),
        "interval": interval,
        "interval_multiplier": interval_multiplier,
        "start_date": sd.isoformat(),
        "end_date": ed.isoformat(),
        "bars": out,
        "count": len(out)
    }
    _log("ok", None)
    return resp

def get_company_news(ticker, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_company_news"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1]
            return datetime.datetime.fromisoformat(v)
        except ValueError:
            return None

    def _log(status, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso()
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfgs = _load("service_config.json")
        cfg = cfgs[0] if isinstance(cfgs, list) and cfgs else (cfgs if isinstance(cfgs, dict) else {})
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        if rate is None and quota is None:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        if rate is not None:
            try:
                rate_i = int(rate)
            except Exception:
                rate_i = None
            if rate_i is not None and rate_i >= 0:
                cutoff = now - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_dt(r.get("ts"))
                    if ts is not None and ts >= cutoff:
                        cnt += 1
                if cnt >= rate_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        if quota is not None:
            try:
                quota_i = int(quota)
            except Exception:
                quota_i = None
            if quota_i is not None and quota_i >= 0:
                day_start = datetime.datetime(now.year, now.month, now.day)
                cnt = 0
                for r in logs:
                    ts = _parse_dt(r.get("ts"))
                    if ts is not None and ts >= day_start:
                        cnt += 1
                if cnt >= quota_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error")
        return limit_err

    if not isinstance(ticker, str) or not ticker.strip():
        _log("error")
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string.")
    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, int):
            _log("error")
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1:
            _log("error")
            return _err("VALIDATION_ERROR", "limit must be >= 1.")
        lim = limit

    instruments = _load("instruments.json")
    t_up = ticker.strip().upper()
    inst = None
    if isinstance(instruments, list):
        for r in instruments:
            if isinstance(r, dict) and (r.get("ticker") or "").upper() == t_up and r.get("asset_class") == "equity" and r.get("status") == "active":
                inst = r
                break
    if inst is None:
        _log("error")
        return _err("NOT_FOUND", "No active equity instrument found for ticker.", ticker=t_up)

    news = _load("company_news.json")
    items = []
    if isinstance(news, list):
        for n in news:
            if not isinstance(n, dict):
                continue
            if n.get("instrument_id") != inst.get("id"):
                continue
            if n.get("status") != "active":
                continue
            items.append(n)

    items.sort(key=lambda x: (_parse_dt(x.get("published_at")) or datetime.datetime.min), reverse=True)
    items = items[:lim]

    _log("ok")
    return {
        "instrument": {
            "id": inst.get("id"),
            "ticker": inst.get("ticker"),
            "asset_class": inst.get("asset_class"),
            "exchange": inst.get("exchange"),
            "name": inst.get("name"),
        },
        "news": items,
        "count": len(items),
        "limit": lim
    }

