            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso()
        })
        _save("request_logs.json", logs)

    def _enforce_limits_or_auth():
        # No explicit credential parameter exists; auth is ambient. Only return UNAUTHORIZED
        # if the store has no configuration enabling service at all (no working combination).
        # Rate/quota enforced if configured.
        cfgs = _load("service_config.json")
        cfg = cfgs[0] if isinstance(cfgs, list) and cfgs else (cfgs if isinstance(cfgs, dict) else {})
        if cfg == {}:
            # if there is also no instruments data, treat as unauthorized/unavailable
            inst = _load("instruments.json")
            if not inst:
                return _err("UNAUTHORIZED", "No active credentials or service configuration available.")
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        if rate is None and quota is None:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        if rate is not None:
            try:
                rate_i = int(rate)
            except Exception:
                rate_i = None
            if rate_i is not None and rate_i >= 0:
                cutoff = now - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = _parse_dt(r.get("ts"))
                    if ts is not None and ts >= cutoff:
                        cnt += 1
                if cnt >= rate_i:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        if quota is not None:
            try:
                quota_i = int(quota)
            except Exception:
                quota_i = None
            if quota_i is not None and quota_i >= 0:
                day_start = datetime.datetime(now.year, now.month, now.day)
                cnt = 0
                for r in logs:
                    ts = _parse_dt(r.get("ts"))
                    if ts is not None and ts >= day_start:
                        cnt += 1
                if cnt >= quota_i:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    err = _enforce_limits_or_auth()
    if err:
        _log("error")
        return err

    instruments = _load("instruments.json")
    tickers = []
    if isinstance(instruments, list):
        for r in instruments:
            if not isinstance(r, dict):
                continue
            if r.get("asset_class") == "crypto" and r.get("status") == "active":
                t = r.get("ticker")
                if isinstance(t, str) and t:
                    tickers.append(t)

    tickers.sort(key=lambda s: s.upper())

    _log("ok")
    return {"tickers": tickers, "count": len(tickers)}

def get_crypto_prices(ticker, start_date, end_date, interval, interval_multiplier, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_crypto_prices"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts_any(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            try:
                d = datetime.datetime.strptime(s, "%Y-%m-%d").date()
                return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            except ValueError:
                return None

    def _parse_date_param(s, field):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a string date", field=field)
        dt = _parse_ts_any(s)
        if not dt:
            return None, _err("VALIDATION_ERROR", f"Invalid {field} format; expected YYYY-MM-DD or ISO 8601 timestamp", field=field)
        return dt, None  # keep full datetime (UTC)

    def _get_requests_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _extract_ts_from_log_row(r):
        if not isinstance(r, dict):
            return None
        for k in ("ts", "timestamp", "created_at", "time"):
            if k in r:
                dt = _parse_ts_any(r.get(k))
                if dt:
                    return dt.astimezone(datetime.timezone.utc)
        return None

    def _extract_endpoint_from_log_row(r):
        if isinstance(r, dict):
            return r.get("endpoint") or r.get("path") or r.get("operation")
        return None

    def _enforce_limits():
        cfg = _load("service_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")

        req_file = _get_requests_file()
        logs = _load(req_file)
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        if isinstance(rate, int) and rate > 0:
            c = 0
            for r in logs:
                if _extract_endpoint_from_log_row(r) != endpoint:
                    continue
                ts = _extract_ts_from_log_row(r)
                if ts and ts >= minute_ago:
                    c += 1
            if c >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)

        if isinstance(quota, int) and quota > 0:
            c = 0
            for r in logs:
                if _extract_endpoint_from_log_row(r) != endpoint:
                    continue
                ts = _extract_ts_from_log_row(r)
                if ts and ts >= day_ago:
                    c += 1
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)

        return None

    def _log(status, extra=None):
        req_file = _get_requests_file()
        logs = _load(req_file)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(req_file, logs)

    # Quota/rate limit before doing work (but still log the refused request)
    lim_err = _enforce_limits()
    if lim_err:
        _log("error", {"error_code": lim_err["error"]["code"]})
        return lim_err

    # Validate inputs
    if not isinstance(ticker, str) or not ticker.strip():
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string", field="ticker")

    if interval not in ("minute", "hour", "day", "week", "month"):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported interval", field="interval", allowed=["minute", "hour", "day", "week", "month"])

    if not isinstance(interval_multiplier, int):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "interval_multiplier must be an integer", field="interval_multiplier")
    if interval_multiplier < 1 or interval_multiplier > 1440:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "interval_multiplier out of range", field="interval_multiplier", minimum=1, maximum=1440)

    sd, e1 = _parse_date_param(start_date, "start_date")
    if e1:
        _log("error", {"error_code": e1["error"]["code"]})
        return e1
    ed, e2 = _parse_date_param(end_date, "end_date")
    if e2:
        _log("error", {"error_code": e2["error"]["code"]})
        return e2

    # Enforce start <= end (inclusive)
    if sd > ed:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_date must be <= end_date", start_date=start_date, end_date=end_date)

    # Resolve instrument by ticker (case-insensitive) and ACTIVE. IMPORTANT:
    # Do NOT force asset_class='crypto' strictly because callers may pass an equity ticker;
    # instead, resolve any active instrument first, then prefer crypto if multiple match.
    instruments = _load("instruments.json")
    if isinstance(instruments, dict) and "rows" in instruments:
        instruments = instruments["rows"]
    if not isinstance(instruments, list):
        instruments = []

    t_up = ticker.strip().upper()
    matches = [r for r in instruments if isinstance(r, dict) and (r.get("ticker") or "").strip().upper() == t_up and r.get("status") == "active"]
    if not matches:
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No active instrument found for ticker", ticker=ticker)

    crypto_matches = [r for r in matches if r.get("asset_class") == "crypto"]
    inst = crypto_matches[0] if crypto_matches else matches[0]
    instrument_id = inst.get("id")

    # Load and filter bars
    bars = _load("price_bars.json")
    if isinstance(bars, dict) and "rows" in bars:
        bars = bars["rows"]
    if not isinstance(bars, list):
        bars = []

    # Inclusive time range: if user provided a date without time, treat start as 00:00:00Z
    # and end as 23:59:59Z to match "inclusive" semantics for date inputs.
    # If they provided a timestamp, use it as-is.
    def _is_date_only(s):
        return isinstance(s, str) and len(s.strip()) == 10 and s.strip()[4] == "-" and s.strip()[7] == "-"

    if _is_date_only(start_date):
        sd_dt = datetime.datetime(sd.year, sd.month, sd.day, tzinfo=datetime.timezone.utc)
    else:
        sd_dt = sd.astimezone(datetime.timezone.utc)

    if _is_date_only(end_date):
        ed_dt = datetime.datetime(ed.year, ed.month, ed.day, 23, 59, 59, tzinfo=datetime.timezone.utc)
    else:
        ed_dt = ed.astimezone(datetime.timezone.utc)

    out = []
    for r in bars:
        if not isinstance(r, dict):
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("interval") != interval:
            continue
        if r.get("interval_multiplier") != interval_multiplier:
            continue
        ts = _parse_ts_any(r.get("ts"))
        if not ts:
            continue
        ts = ts.astimezone(datetime.timezone.utc)
        if ts < sd_dt or ts > ed_dt:
            continue
        out.append((ts, r))

    out.sort(key=lambda x: x[0])  # time-ordered list

    result_rows = [r for _, r in out]
    _log("ok", {"rows": len(result_rows), "instrument_id": instrument_id})
    return {
        "ticker": inst.get("ticker"),
        "instrument_id": instrument_id,
        "asset_class": inst.get("asset_class"),
        "interval": interval,
        "interval_multiplier": interval_multiplier,
        "start_date": start_date,
        "end_date": end_date,
        "bars": result_rows,
        "count": len(result_rows),
    }

