                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            try:
                d = datetime.datetime.strptime(s, "%Y-%m-%d").date()
                return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
            except ValueError:
                return None

    def _get_requests_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _enforce_and_log(status, credential_used=None, error_code=None):
        fn = _get_requests_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-5000:]:
            ts = _parse_dt(r.get("timestamp") if isinstance(r, dict) else None) if isinstance(r, dict) else None
            if ts and ts >= window_start:
                recent += 1
        if recent >= 60:
            rec = {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": "error",
                "error_code": "RATE_LIMIT",
                "credential": credential_used,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(rec)
            _save(fn, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        day_count = 0
        for r in logs[-200000:]:
            ts = _parse_dt(r.get("timestamp") if isinstance(r, dict) else None) if isinstance(r, dict) else None
            if ts and ts >= day_start:
                day_count += 1
        if day_count >= 10000:
            rec = {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": "error",
                "error_code": "QUOTA_EXCEEDED",
                "credential": credential_used,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(rec)
            _save(fn, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        rec = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "error_code": error_code,
            "credential": credential_used,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(rec)
        _save(fn, logs)
        return None

    if not isinstance(ticker, str) or not ticker.strip():
        e = _err("VALIDATION_ERROR", "ticker must be a non-empty string", field="ticker")
        rl = _enforce_and_log("error", error_code=e["error"]["code"])
        return rl or e

    if limit is None:
        limit_val = 10
    else:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e
        if limit < 1 or limit > 500:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e
        limit_val = limit

    if filing_type is not None and (not isinstance(filing_type, str) or not filing_type.strip()):
        e = _err("VALIDATION_ERROR", "filing_type must be a non-empty string when provided", field="filing_type")
        rl = _enforce_and_log("error", error_code=e["error"]["code"])
        return rl or e

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    t_up = ticker.strip().upper()
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("asset_class") == "equity" and r.get("status") == "active":
            if isinstance(r.get("ticker"), str) and r.get("ticker").upper() == t_up:
                inst = r
                break
    if not inst:
        e = _err("NOT_FOUND", "No active equity instrument found for ticker", ticker=ticker)
        rl = _enforce_and_log("error", error_code=e["error"]["code"])
        return rl or e

    filings = _load("sec_filings.json")
    if not isinstance(filings, list):
        filings = []

    inst_id = inst.get("id")
    out = []
    for f in filings:
        if not isinstance(f, dict):
            continue
        if f.get("instrument_id") != inst_id:
            continue
        if f.get("status") not in ("available", "superseded"):
            continue
        if filing_type is not None and f.get("filing_type") != filing_type:
            continue
        out.append(f)

    out.sort(key=lambda x: (_parse_dt(x.get("filed_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    out_limited = out[:limit_val]

    rl = _enforce_and_log("ok")
    if rl:
        return rl

    return {
        "ticker": inst.get("ticker"),
        "instrument_id": inst_id,
        "count": len(out_limited),
        "filings": out_limited,
        "limit": limit_val,
        "filing_type": filing_type,
    }

def list_instruments(asset_class=None, status=None, exchange=None, currency=None, sector=None, industry=None, ticker_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_instruments"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _get_requests_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _enforce_and_log(status_val, credential_used=None, error_code=None):
        fn = _get_requests_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-5000:]:
            ts = _parse_dt(r.get("timestamp") if isinstance(r, dict) else None) if isinstance(r, dict) else None
            if ts and ts >= window_start:
                recent += 1
        if recent >= 60:
            rec = {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": "error",
                "error_code": "RATE_LIMIT",
                "credential": credential_used,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(rec)
            _save(fn, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")

        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        day_count = 0
        for r in logs[-200000:]:
            ts = _parse_dt(r.get("timestamp") if isinstance(r, dict) else None) if isinstance(r, dict) else None
            if ts and ts >= day_start:
                day_count += 1
        if day_count >= 10000:
            rec = {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": "error",
                "error_code": "QUOTA_EXCEEDED",
                "credential": credential_used,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(rec)
            _save(fn, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        rec = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status_val,
            "error_code": error_code,
            "credential": credential_used,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(rec)
        _save(fn, logs)
        return None

    # Validate filters
    if asset_class is not None and asset_class not in ("equity", "crypto"):
        e = _err("VALIDATION_ERROR", "Invalid asset_class", field="asset_class", allowed=["equity", "crypto"])
        rl = _enforce_and_log("error", error_code=e["error"]["code"])
        return rl or e
    if status is not None and status not in ("active", "inactive", "delisted"):
        e = _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "inactive", "delisted"])
        rl = _enforce_and_log("error", error_code=e["error"]["code"])
        return rl or e
    for fld, val in (("exchange", exchange), ("currency", currency), ("sector", sector), ("industry", industry), ("ticker_prefix", ticker_prefix)):
        if val is not None and (not isinstance(val, str)):
            e = _err("VALIDATION_ERROR", f"{fld} must be a string", field=fld)
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e

    if limit is None:
        limit_val = 100
    else:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e
        if limit < 1 or limit > 500:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e
        limit_val = limit

    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            e = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e
        # cursor is base64url of ticker upper (or "t:<TICKER>")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("t:"):
                start_after = s[2:].upper()
            else:
                start_after = s.upper()
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            rl = _enforce_and_log("error", error_code=e["error"]["code"])
            return rl or e

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    # Filter
    rows = []
    tp = ticker_prefix.strip().upper() if isinstance(ticker_prefix, str) and ticker_prefix.strip() else None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if asset_class is not None and r.get("asset_class") != asset_class:
            continue
        if status is not None and r.get("status") != status:
            continue
        if exchange is not None:
            if r.get("exchange") != exchange:
                continue
        if currency is not None:
            if r.get("currency") != currency:
                continue
        if sector is not None:
            if r.get("sector") != sector:
                continue
        if industry is not None:
            if r.get("industry") != industry:
                continue
        t = r.get("ticker")
        if not isinstance(t, str) or not t:
            continue
        if tp is not None and not t.upper().startswith(tp):
            continue
        rows.append(r)

    # Order by ticker asc (case-insensitive)
    rows.sort(key=lambda x: (str(x.get("ticker", "")).upper(), str(x.get("id", ""))))

    # Apply cursor (start_after is ticker upper)
    if start_after is not None:
        filtered = []
        for r in rows:
            t = str(r.get("ticker", "")).upper()
            if t > start_after:
                filtered.append(r)
        rows = filtered

    page = rows[:limit_val]
    has_more = len(rows) > len(page)

    next_cursor = None
    if has_more and page:
        last_t = str(page[-1].get("ticker", "")).upper()
        payload = ("t:" + last_t).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    rl = _enforce_and_log("ok")
    if rl:
        return rl

    return {
        "data": page,
        "total": len(rows),
        "limit": limit_val,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_instrument(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_instrument"
    status = "ok"
    credential_used = None

    def _log_call(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "credential_id": credential_used,
        }
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        day = now[:10]
        u = None
        for r in usage:
            if isinstance(r, dict) and r.get("date") == day:
                u = r
                break
        if u is None:
            u = {"date": day, "calls": 0, "mutations": 0}
            usage.append(u)
        u["calls"] = int(u.get("calls", 0) or 0) + 1
        _save("usage.json", usage)

        # Quota/rate limiting (best-effort if no policy file exists)
        policy = _load("service_policy.json")
        if isinstance(policy, dict):
            max_per_day = policy.get("quota_per_day")
            if isinstance(max_per_day, int) and max_per_day >= 0:
                calls_today = u["calls"]
                if calls_today > max_per_day:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=max_per_day, calls_today=calls_today)
            rpm = policy.get("rate_limit_per_minute")
            if isinstance(rpm, int) and rpm >= 1:
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                recent = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = r.get("ts")
                    if isinstance(ts, str):
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            recent += 1
                if recent > rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rpm)
        return None

    # Validate
    if not isinstance(id, str):
        status = "error"
        out = _err("VALIDATION_ERROR", "Parameter 'id' must be a string.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    if id.strip() == "":
        status = "error"
        out = _err("VALIDATION_ERROR", "Parameter 'id' must not be empty.")
        _log_call("error", "VALIDATION_ERROR")
        return out

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("id") == id:
            inst = r
            break

    if inst is None:
        status = "error"
        out = _err("NOT_FOUND", "Instrument not found.", id=id)
        _log_call("error", "NOT_FOUND")
        return out

    quota_err = _log_call("ok", None)
    if quota_err:
        return quota_err

    return {"instrument": inst}

def resolve_ticker(ticker, asset_class=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "resolve_ticker"
    credential_used = None

    def _log_call(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "credential_id": credential_used,
        }
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        day = now[:10]
        u = None
        for r in usage:
            if isinstance(r, dict) and r.get("date") == day:
                u = r
                break
        if u is None:
            u = {"date": day, "calls": 0, "mutations": 0}
            usage.append(u)
        u["calls"] = int(u.get("calls", 0) or 0) + 1
        _save("usage.json", usage)

        policy = _load("service_policy.json")
        if isinstance(policy, dict):
            max_per_day = policy.get("quota_per_day")
            if isinstance(max_per_day, int) and max_per_day >= 0:
                calls_today = u["calls"]
                if calls_today > max_per_day:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=max_per_day, calls_today=calls_today)
            rpm = policy.get("rate_limit_per_minute")
            if isinstance(rpm, int) and rpm >= 1:
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                recent = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = r.get("ts")
                    if isinstance(ts, str):
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            recent += 1
                if recent > rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rpm)
        return None

    # Validate
    if not isinstance(ticker, str):
        out = _err("VALIDATION_ERROR", "Parameter 'ticker' must be a string.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    t = ticker.strip()
    if t == "":
        out = _err("VALIDATION_ERROR", "Ticker must not be empty.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    # allow common ticker chars; keep permissive but block control chars
    if any(ord(ch) < 32 for ch in t):
        out = _err("VALIDATION_ERROR", "Ticker contains invalid characters.")
        _log_call("error", "VALIDATION_ERROR")
        return out

    if asset_class is not None:
        if not isinstance(asset_class, str):
            out = _err("VALIDATION_ERROR", "Parameter 'asset_class' must be a string when provided.")
            _log_call("error", "VALIDATION_ERROR")
            return out
        if asset_class not in ("equity", "crypto"):
            out = _err("VALIDATION_ERROR", "Parameter 'asset_class' must be one of: equity, crypto.")
            _log_call("error", "VALIDATION_ERROR")
            return out

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    target = t.upper()
    matches = []
    for r in instruments:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        rt = r.get("ticker")
        if isinstance(rt, str) and rt.upper() == target:
            if asset_class is None or r.get("asset_class") == asset_class:
                matches.append(r)

    if not matches:
        out = _err("NOT_FOUND", "No active instrument found for ticker.", ticker=t, asset_class=asset_class)
        _log_call("error", "NOT_FOUND")
        return out

    # If ambiguous, choose deterministic: prefer equity over crypto? Spec says returns single active instrument,
    # asset_class can disambiguate; otherwise pick lexicographically smallest id for stability.
    matches.sort(key=lambda x: (str(x.get("asset_class") or ""), str(x.get("ticker") or ""), str(x.get("id") or "")))
    inst = matches[0]

    quota_err = _log_call("ok", None)
    if quota_err:
        return quota_err

    return {"instrument": inst}

def update_instrument_status(id, status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0402000" if __import__("os").path.isdir("./environment_mix/0402000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_instrument_status"
    credential_used = None

    def _log_call(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": now,
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "credential_id": credential_used,
        }
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        day = now[:10]
        u = None
        for r in usage:
            if isinstance(r, dict) and r.get("date") == day:
                u = r
                break
        if u is None:
            u = {"date": day, "calls": 0, "mutations": 0}
            usage.append(u)
        u["calls"] = int(u.get("calls", 0) or 0) + 1
        u["mutations"] = int(u.get("mutations", 0) or 0) + 1
        _save("usage.json", usage)

        policy = _load("service_policy.json")
        if isinstance(policy, dict):
            max_per_day = policy.get("quota_per_day")
            if isinstance(max_per_day, int) and max_per_day >= 0:
                calls_today = u["calls"]
                if calls_today > max_per_day:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=max_per_day, calls_today=calls_today)
            rpm = policy.get("rate_limit_per_minute")
            if isinstance(rpm, int) and rpm >= 1:
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                recent = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = r.get("ts")
                    if isinstance(ts, str):
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            recent += 1
                if recent > rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rpm)
        return None

    # Validate
    if not isinstance(id, str):
        out = _err("VALIDATION_ERROR", "Parameter 'id' must be a string.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    if id.strip() == "":
        out = _err("VALIDATION_ERROR", "Parameter 'id' must not be empty.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    if not isinstance(status, str):
        out = _err("VALIDATION_ERROR", "Parameter 'status' must be a string.")
        _log_call("error", "VALIDATION_ERROR")
        return out
    if status not in ("active", "inactive", "delisted"):
        out = _err("VALIDATION_ERROR", "Parameter 'status' must be one of: active, inactive, delisted.")
        _log_call("error", "VALIDATION_ERROR")
        return out

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []

    idx = None
    inst = None
    for i, r in enumerate(instruments):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            inst = r
            break

    if inst is None:
        out = _err("NOT_FOUND", "Instrument not found.", id=id)
        _log_call("error", "NOT_FOUND")
        return out

    current = inst.get("status")
    allowed = {
        "active": {"inactive", "delisted"},
        "inactive": {"active", "delisted"},
        "delisted": set(),
    }
    if current not in allowed:
        out = _err("CONFLICT", "Instrument has an unknown current status; cannot transition.", current_status=current)
        _log_call("error", "CONFLICT")
        return out

    # Idempotent if same status
    if status == current:
        # Still log usage/quota effects as a real call; but no mutation should be claimed as "success without effect"?
        # This is an idempotent update: returning the row is acceptable.
        quota_err = _log_call("ok", None)
        if quota_err:
            return quota_err
        return {"instrument": inst}

    if status not in allowed[current]:
        out = _err("CONFLICT", "Status transition not allowed.", from_status=current, to_status=status)
        _log_call("error", "CONFLICT")
        return out

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_inst = dict(inst)
    new_inst["status"] = status
    new_inst["updated_at"] = now
    instruments[idx] = new_inst
    _save("instruments.json", instruments)

    audit = _load("audit_log.json")
    if not isinstance(audit, list):
        audit = []
    audit.append({
        "id": f"aud_{int(time.time()*1000)}_{len(audit)+1}",
        "ts": now,
        "entity": "instrument",
        "entity_id": id,
        "action": "update_status",
        "from": current,
        "to": status,
        "endpoint": endpoint,
        "credential_id": credential_used,
    })
    _save("audit_log.json", audit)

    quota_err = _log_call("ok", None)
    if quota_err:
        return quota_err

    return {"instrument": new_inst}
